// Примечание: API @jinx-ui/react взят по core-8 runtime (Alert, Button, Field, Input, Select, Switch);
// если имена пропов в вашей версии отличаются, правки точечные — логика формы от них не зависит.
import { useId, useState, type FormEvent } from 'react';
import { Alert, Button, Field, Input, Select, Switch } from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLES: { value: Role; label: string }[] = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const emailId = useId();
  const roleId = useId();
  const notifyId = useId();

  const [email, setEmail] = useState('');
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_RE.test(email.trim());
  const error = touched && !isValid ? 'Введите адрес вида name@company.com' : undefined;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;

    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  }

  return (
    <div
      className="jx-stack"
      style={{ display: 'grid', gap: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-form, 420px)' }}
    >
      {invited && (
        <Alert
          tone="success"
          closable
          onClose={() => setInvited(null)}
          title="Приглашение отправлено"
        >
          {invited} получит доступ к команде.
        </Alert>
      )}

      <form className="jx-form" onSubmit={handleSubmit} noValidate>
        <div className="jx-stack" style={{ display: 'grid', gap: 'var(--jx-space-4)' }}>
          <Field
            htmlFor={emailId}
            label="Почта участника"
            hint="Приглашение действует 7 дней."
            error={error}
          >
            <Input
              id={emailId}
              type="email"
              name="email"
              value={email}
              placeholder="name@company.com"
              invalid={Boolean(error)}
              autoComplete="email"
              onChange={(event) => setEmail(event.target.value)}
              onBlur={() => setTouched(true)}
            />
          </Field>

          <Field htmlFor={roleId} label="Роль">
            <Select
              id={roleId}
              name="role"
              value={role}
              options={ROLES}
              onChange={(value: Role) => setRole(value)}
            />
          </Field>

          <Switch
            id={notifyId}
            name="notify"
            checked={notify}
            label="Отправить уведомление"
            onChange={(checked: boolean) => setNotify(checked)}
          />

          <Button type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </Button>
        </div>
      </form>
    </div>
  );
}

